#include "completion_gate.h"
namespace grs::g9dm {
std::optional<ValidatedRecord> CompletionGate::Accepted(const Permit& p,const accept647::ExpectedContract& e,const accept647::NativeMappedObservation& o){if(e.SelectedFamily()!=accept647::Family::DM_DEFAULT)return {};auto proof=accept647::SemanticCore::Accepted(e,o);if(!proof)return {};return ValidatedRecord(p,*proof);}
std::optional<ValidatedBlockedControlRecord> CompletionGate::Blocked(const Permit& p,const accept647::ExpectedContract& e,const accept647::NativeMappedObservation& o){if(e.SelectedFamily()!=accept647::Family::DM_DEFAULT)return {};auto proof=accept647::SemanticCore::Blocked(e,o);if(!proof)return {};return ValidatedBlockedControlRecord(p,*proof);}
std::optional<ValidatedCompositeParentDM> CompletionGate::AcceptedComposite(const accept647::CompositeExpectedContract& e,const accept647::NativeMappedObservation& o){if(e.SelectedFamily()!=accept647::Family::G11_DM)return {};auto proof=accept647::SemanticCore::Accepted(e,o);if(!proof)return {};return ValidatedCompositeParentDM(*proof);}
std::optional<ValidatedBlockedCompositeParentDM> CompletionGate::BlockedComposite(const accept647::CompositeExpectedContract& e,const accept647::NativeMappedObservation& o){if(e.SelectedFamily()!=accept647::Family::G11_DM)return {};auto proof=accept647::SemanticCore::Blocked(e,o);if(!proof)return {};return ValidatedBlockedCompositeParentDM(*proof);}
}
